import { test, expect, eventsTestConfig } from './fixtures';
import { SEEDED_EVENT_LEINSTER_OPEN_MAT } from './seeded';

test.use(eventsTestConfig);

test.describe('Events header', { tag: ['@events', '@ui', '@desktop'] }, () => {
  test('visitor should see events-page-header-total text', { tag: '@acceptance' }, async ({ page }) => {
    await page.goto('/events');
    const total = await page.getByTestId('events-page-header-total').textContent();
    expect(total).toContain('Found');
    await expect(page.getByText(SEEDED_EVENT_LEINSTER_OPEN_MAT.name)).toBeVisible();
  });
});
